1://! Event-driven observation of autonomous native cron executions.
2://!
3://! `/api/events` is a wakeup source only. The event payload is never persisted,
4://! logged, or projected. Every accepted `cron_result` causes one complete,
5://! bounded `/api/cron` readback, which MutationEngine commits before notifying
6://! its consumers.
7:
8:use crate::{
9:    cron_dispatch, cron_gateway::TchedRouterCronGateway, cron_methods::CronMethods,
10:    mutation_engine::MutationEngine, tched_router_runtime::TchedRouterRuntimeClient,
11:};
12:use anyhow::{Context, Result, bail, ensure};
13:use futures::StreamExt;
14:use std::{future::Future, sync::Arc, time::Duration};
15:
16:const MAX_SSE_FRAME_BYTES: usize = 256 * 1024;
17:const MAX_WAKEUPS_PER_CHUNK: usize = 1024;
18:const MAX_RECONNECTS: usize = 8;
19:const RECONNECT_DELAYS: [Duration; MAX_RECONNECTS] = [
20:    Duration::from_millis(250),
21:    Duration::from_millis(500),
22:    Duration::from_secs(1),
23:    Duration::from_secs(2),
24:    Duration::from_secs(4),
25:    Duration::from_secs(5),
26:    Duration::from_secs(5),
27:    Duration::from_secs(5),
28:];
29:
30:#[derive(Debug, Clone, Copy, PartialEq, Eq)]
31:enum Wakeup {
32:    CronResult,
33:    Gap,
34:}
35:
36:#[derive(Default)]
37:struct SseDecoder {
38:    pending: Vec<u8>,
39:}
40:
41:impl SseDecoder {
42:    fn push(&mut self, chunk: &[u8]) -> Result<Vec<Wakeup>> {
43:        let mut wakeups = Vec::new();
44:        for byte in chunk {
45:            self.pending.push(*byte);
46:            let delimiter_len = if self.pending.ends_with(b"\r\n\r\n") {
47:                Some(4)
48:            } else if self.pending.ends_with(b"\n\n") {
49:                Some(2)
50:            } else {
51:                None
52:            };
53:            ensure!(
54:                self.pending.len() <= MAX_SSE_FRAME_BYTES,
55:                "native event frame exceeds {MAX_SSE_FRAME_BYTES} bytes"
56:            );
57:            let Some(delimiter_len) = delimiter_len else {
58:                continue;
59:            };
60:            self.pending.truncate(self.pending.len() - delimiter_len);
61:            let frame = std::mem::take(&mut self.pending);
62:            if let Some(wakeup) = parse_frame(&frame)? {
63:                wakeups.push(wakeup);
64:                ensure!(
65:                    wakeups.len() <= MAX_WAKEUPS_PER_CHUNK,
66:                    "native event chunk contains more than {MAX_WAKEUPS_PER_CHUNK} state wakeups"
67:                );
68:            }
69:        }
70:        Ok(wakeups)
71:    }
72:
73:    fn finish(self) -> Result<()> {
74:        ensure!(
75:            self.pending.iter().all(u8::is_ascii_whitespace),
76:            "native event stream ended with a truncated frame"
77:        );
78:        Ok(())
79:    }
80:}
81:
82:fn parse_frame(frame: &[u8]) -> Result<Option<Wakeup>> {
83:    let frame = std::str::from_utf8(frame).context("native event frame is not UTF-8")?;
84:    let mut event_name = None;
85:    let mut data = String::new();
86:    for line in frame.lines() {
87:        let line = line.strip_suffix('\r').unwrap_or(line);
88:        if line.starts_with(':') || line.is_empty() {
89:            continue;
90:        }
91:        if let Some(value) = line.strip_prefix("event:") {
92:            event_name = Some(value.trim());
93:        } else if let Some(value) = line.strip_prefix("data:") {
94:            if !data.is_empty() {
95:                data.push('\n');
96:            }
97:            data.push_str(value.strip_prefix(' ').unwrap_or(value));
98:            ensure!(
99:                data.len() <= MAX_SSE_FRAME_BYTES,
100:                "native event data exceeds {MAX_SSE_FRAME_BYTES} bytes"
101:            );
102:        }
103:    }
104:    if event_name == Some("gap") {
105:        return Ok(Some(Wakeup::Gap));
106:    }
107:    if data.is_empty() {
108:        return Ok(None);
109:    }
110:
111:    // Parse only long enough to identify the wakeup. In particular, never
112:    // retain, return, or log the native `output` field carried by cron_result.
113:    let value: serde_json::Value =
114:        serde_json::from_str(&data).context("native event data is invalid JSON")?;
115:    if value.get("type").and_then(serde_json::Value::as_str) != Some("cron_result") {
116:        return Ok(None);
117:    }
118:    let job_id = value
119:        .get("job_id")
120:        .and_then(serde_json::Value::as_str)
121:        .context("native cron_result has no job_id")?;
122:    ensure!(
123:        !job_id.is_empty() && job_id.len() <= 256 && !job_id.chars().any(char::is_control),
124:        "native cron_result has an invalid job_id"
125:    );
126:    Ok(Some(Wakeup::CronResult))
127:}
