129:async fn observe_connection(
130:    engine: &MutationEngine,
131:    client: &TchedRouterRuntimeClient,
132:    methods: &CronMethods,
133:) -> Result<()> {
134:    // Subscribe before the first hydration. Events produced during the bounded
135:    // readback queue in the native response rather than falling into a gap.
136:    let response = client
137:        .open_gateway_event_stream()
138:        .await
139:        .map_err(|_| anyhow::anyhow!("native cron event subscription is unavailable"))?;
140:    drive_event_stream(response.bytes_stream(), || async {
141:        cron_dispatch::publish_observed_snapshot(engine, methods).await
142:    })
143:    .await
144:}
145:
146:async fn drive_event_stream<S, B, E, P, F>(stream: S, mut publish: P) -> Result<()>
147:where
148:    S: futures::Stream<Item = std::result::Result<B, E>>,
149:    B: AsRef<[u8]>,
150:    E: std::fmt::Display,
151:    P: FnMut() -> F,
152:    F: Future<Output = Result<()>>,
153:{
154:    // The caller has already established the subscription. This initial
155:    // complete readback closes the subscribe/hydrate race.
156:    publish()
157:        .await
158:        .context("initial native cron snapshot publication failed")?;
159:    let mut decoder = SseDecoder::default();
160:    futures::pin_mut!(stream);
161:    while let Some(chunk) = stream.next().await {
162:        let chunk = chunk.map_err(|_| anyhow::anyhow!("native cron event stream failed"))?;
163:        for wakeup in decoder.push(chunk.as_ref())? {
164:            match wakeup {
165:                Wakeup::CronResult => {
166:                    publish()
167:                        .await
168:                        .context("cron_result snapshot publication failed")?;
169:                }
170:                Wakeup::Gap => bail!("native cron event stream reported a delivery gap"),
171:            }
172:        }
173:    }
174:    decoder.finish()?;
175:    bail!("native cron event stream closed")
176:}
