178:/// Observe native cron wakeups with a finite reconnect budget. Reconnection is
179:/// attempted only after an explicit stream close/error/gap. Every newly opened
180:/// stream is established before its rehydration read; there is no polling or
181:/// heartbeat-triggered state read.
182:pub(crate) async fn observe(engine: Arc<MutationEngine>) -> Result<()> {
183:    let client = TchedRouterRuntimeClient::from_env();
184:    let gateway = Arc::new(TchedRouterCronGateway::from_client(client.clone()));
185:    let methods = CronMethods::new(gateway);
186:
187:    let mut last_error = None;
188:    for attempt in 0..=MAX_RECONNECTS {
189:        if attempt > 0 {
190:            tokio::time::sleep(RECONNECT_DELAYS[attempt - 1]).await;
191:        }
192:        match observe_connection(&engine, &client, &methods).await {
193:            Ok(()) => return Ok(()),
194:            Err(error) => last_error = Some(error),
195:        }
196:    }
197:    Err(last_error.unwrap_or_else(|| anyhow::anyhow!("native cron observer ended")))
198:        .context("native cron observer exhausted its bounded reconnect budget")
199:}
