pub(crate) fn container_label(record: &NativeCreationRecord) -> Result<Option<String>> {
    let body: Value = serde_json::from_str(&record.request.request_json)?;
    match body["config"].get("user.opdbus.naming_version") {
        None => Ok(None),
        Some(Value::String(version)) if version == "1" => Ok(Some(
            incus::container_label_for_native_name(&record.name)
                .context("numbered creation has an invalid native name")?)),
        _ => anyhow::bail!("unsupported native naming policy"),
    }
}

fn resolved_body(record: &NativeCreationRecord) -> Result<Value> {
    let mut body: Value = serde_json::from_str(&record.request.request_json)?;
    body["name"] = record.name.clone().into();
    body["config"]["user.opdbus.creation_operation"] = record.request.operation_id.clone().into();
    body["config"]["user.opdbus.creation_digest"] = record.request.request_digest.clone().into();
    if let Some(label) = container_label(record)? {
        body["config"]["user.display_name"] = label.clone().into();
        body["config"]["user.opdbus.container_label"] = label.clone().into();
        if body["type"] == "container" {
            let raw = body["config"]["raw.lxc"].as_str().unwrap_or("");
            let mut raw = raw.to_owned();
            if !raw.is_empty() && !raw.ends_with('\n') { raw.push('\n'); }
            raw.push_str(&format!("lxc.uts.name = {label}"));
            body["config"]["raw.lxc"] = raw.into();
        }
    }
    Ok(body)
}

