pub(crate) async fn invoke(
    engine: &MutationEngine, plugin: &str, method: &str, arguments: Value,
    caller: &GhostbridgeIdentity, capability: Option<&str>, proof: Option<BoundOracleProof>,
    source_schema_hash: &str,
) -> Result<Value> {
    invoke_operation(engine, plugin, method, arguments, caller, capability, proof,
        source_schema_hash, tched_fs::mounted::AdmittedOperation::Mounted, Deadline::application(), None).await
}

/// Inner admitted threetched effect: execute in the same verified guest,
/// without re-entering its mounted operation or acquiring another effect lock.
pub(crate) async fn execute_application(
    engine: &MutationEngine, method: &str, arguments: Value,
    caller: &GhostbridgeIdentity, capability: Option<&str>, proof: Option<BoundOracleProof>,
    source_schema_hash: &str, input: String, context: &CallContext,
) -> Result<Value> {
    context.revalidate(engine).await?;
    let origin = context.ticket.as_ref().map(|(_, ticket)| ticket.clone())
        .context("application execution requires its originating mounted admission")?;
    invoke_operation(engine, "threetched", method, arguments, caller, capability, proof,
        source_schema_hash, tched_fs::mounted::AdmittedOperation::Application { input }, context.deadline(), Some(origin)).await
}

async fn prepare_ticket(
    engine: &MutationEngine, plugin: &str, method: &str, arguments: Value,
    caller: &GhostbridgeIdentity, capability: Option<&str>, proof: Option<BoundOracleProof>,
    source_schema_hash: &str, operation: Option<tched_fs::mounted::AdmittedOperation>, deadline: Deadline,
    origin: Option<Arc<Ticket>>, response: Option<crate::chat_response_turns::PendingTurn>,
) -> Result<(Arc<Ticket>, crate::sealed_schema_reader::ManifestPinnedSchemaDocument)> {
    // Retired vendor extension: stale captures must not execute it through the
    // generic command runner after its custom admission callback is removed.
    ensure!(plugin != "threetched" || method != "stateless-generate",
        "patched foundation generation is unsupported; no native effect was attempted");
    let application = matches!(&operation, Some(tched_fs::mounted::AdmittedOperation::Application { .. }));
    let direct = operation.is_none();
    let bytes = tickets().bytes.clone().try_acquire_many_owned(TICKET_CHARGE)
        .context("mounted ingress byte capacity exhausted")?;
    let session = crate::project_dispatch::verified_session(engine, &caller.principal_id,
        Some(&caller.session_id), Some(&caller.session_genesis)).await?;
